        items.push_back(x);
        return true;
    }

    bool dequeue() {
        if (items.empty()) return false;
        items.erase(items.begin());
        return true;
    }

    int front() {
        return items.empty() ? -1 : items.front();
    }

    int rear() {
        return items.empty() ? -1 : items.back();
    }

    bool isEmpty() {
        return items.empty();
    }

    bool isFull() {
        return (int) items.size() == k;
    }
};

